final_sql:
SELECT CAST(SUM(DOCType = 'Unified School District') AS REAL) / SUM(DOCType = 'Elementary School District') AS ratio
FROM schools
WHERE County = 'Orange' AND StatusType = 'Merged';

SELECT f.`Percent (%) Eligible Free (K-12)`, f.`District Code`
FROM schools s JOIN frpm f ON f.CDSCode = s.CDSCode
WHERE s.AdmFName1 = 'Alusine' OR s.AdmFName2 = 'Alusine' OR s.AdmFName3 = 'Alusine';

SELECT f.`Free Meal Count (K-12)` / f.`Enrollment (K-12)` * 100 AS `Percent (%) Eligible Free (K-12)`, f.`District Code`
FROM schools s JOIN frpm f ON s.CDSCode = f.CDSCode
WHERE s.AdmFName1 = 'Alusine' OR s.AdmFName2 = 'Alusine' OR s.AdmFName3 = 'Alusine';

SELECT s.School, s.Street || ', ' || s.City || ', ' || s.State || ' ' || s.Zip AS Address
FROM schools s JOIN frpm f ON s.CDSCode = f.CDSCode
WHERE s.County = 'Monterey' AND f."School Type" = 'High Schools (Public)' AND f."FRPM Count (Ages 5-17)" > 800;

SELECT SUM(f.`Enrollment (Ages 5-17)`)
FROM frpm f JOIN schools s ON f.CDSCode = s.CDSCode
WHERE f.`School Type` = 'State Special Schools' AND s.City = 'Fremont';

SELECT sc.AdmFName1 || ' ' || sc.AdmLName1 AS full_name
FROM satscores sa JOIN schools sc ON sa.cds = sc.CDSCode
ORDER BY sa.NumGE1500 DESC LIMIT 1;

SELECT f."Percent (%) Eligible Free (K-12)", f."District Code"
FROM frpm f JOIN schools s ON f.CDSCode = s.CDSCode
WHERE s.AdmFName1='Alusine' OR s.AdmFName2='Alusine' OR s.AdmFName3='Alusine';

SELECT SUM(f."Enrollment (Ages 5-17)")
FROM schools s JOIN frpm f ON s.CDSCode = f.CDSCode
WHERE s.City = 'Fremont' AND s.SOCType = 'State Special Schools';
